mapper.select:
SELECT p.*, (SELECT COUNT(*) FROM sku WHERE product_id = p.id AND shop_id = #{shopId}) AS sku_count, (SELECT MIN(price) FROM sku WHERE product_id = p.id AND shop_id = #{shopId}) AS min_price FROM product p
AND p.name LIKE CONCAT('%', #{keyword}, '%')
AND p.type = #{type}
AND p.status = #{status}
ORDER BY p.sort ASC, p.id DESC

SELECT p.*, (SELECT COUNT(*) FROM sku s WHERE s.product_id = p.id AND s.shop_id = #{shopId} AND s.status = 'ON_SALE') AS sku_count, (SELECT MIN(price) FROM sku s WHERE s.product_id = p.id AND s.shop_id = #{shopId} AND s.status = 'ON_SALE') AS min_price FROM product p WHERE p.status = 'ON_SALE'
AND p.type = #{type}
AND EXISTS ( SELECT 1 FROM sku s2 WHERE s2.product_id = p.id AND s2.shop_id = #{shopId} AND s2.status = 'ON_SALE' ) ORDER BY p.sort ASC, p.id DESC

SELECT p.*, s.id AS sku_id, s.shop_id AS sku_shop_id, s.product_id AS sku_product_id, s.spec_name AS sku_spec_name, s.price AS sku_price, s.member_price AS sku_member_price, s.img_url AS sku_img_url, s.duration AS sku_duration, s.stock AS sku_stock, s.status AS sku_status, s.sort AS sku_sort, s.create_time AS sku_create_time, s.update_time AS sku_update_time FROM product p LEFT JOIN sku s ON p.id = s.product_id AND s.shop_id = #{shopId}
AND s.status = 'ON_SALE'
WHERE p.id = #{id} ORDER BY s.sort ASC, s.id ASC
